      "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" font-size=\"36\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Quiz: One-Liner Formula</text><text x=\"550\" y=\"115\" font-size=\"24\" fill=\"#a0a0c0\" text-anchor=\"middle\">Four boxes. One sentence.</text><rect x=\"100\" y=\"350\" width=\"900\" height=\"350\" fill=\"#2a2a4e\" stroke=\"#ffd700\" stroke-width=\"4\" rx=\"20\"/><text x=\"550\" y=\"430\" font-size=\"24\" fill=\"#ffd700\" text-anchor=\"middle\">\"Most [HERO] struggle</text><text x=\"550\" y=\"475\" font-size=\"24\" fill=\"#ffd700\" text-anchor=\"middle\">with [PROBLEM].</text><text x=\"550\" y=\"540\" font-size=\"24\" fill=\"#ffd700\" text-anchor=\"middle\">We help them [OUTCOME]</text><text x=\"550\" y=\"585\" font-size=\"24\" fill=\"#ffd700\" text-anchor=\"middle\">so they can [SUCCESS].\"</text><text x=\"550\" y=\"660\" font-size=\"18\" fill=\"#a0a0c0\" text-anchor=\"middle\">Character · Problem · Plan · Success</text><text x=\"550\" y=\"850\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Memorize. Recite. Test on strangers.</text></svg>",
